{"analysis":{"concepts":["Biến đổi đại số","Hoàn thành bình phương","Xét trường hợp","Điều kiện phân biệt"],"constraints":["Bốn số đôi một phân biệt","Tổng trên cạnh AB bằng 0","Tổng trên ba cạnh còn lại là 1, 2, 3 (theo một thứ tự nào đó)"],"givens":["Hình vuông ABCD","Bốn số thực ở bốn đỉnh, đôi một phân biệt","Tổng hai số ở hai đầu cạnh AB bằng 0","Tổng hai số ở hai đầu ba cạnh còn lại (BC, CD, DA) là ba giá trị phân biệt 1, 2, 3"],"gradeLevel":9,"interpretationNotes":[],"language":"vi","statement":"","status":"solvable","statusReason":"","subtopic":"Cực trị (tối thiểu) với ràng buộc đại số","techniques":["substitution","complete_square","case_analysis","equality_case"],"topic":"system","unknowns":["Cách ghi bốn số ở bốn đỉnh sao cho tổng bình phương nhỏ nhất"],"withinCurriculum":true},"answerChecks":[{"assignments":[],"expected":"19/4","kind":"value","statements":["5 - (-2)^2/(4*4)"]}],"figure":{"angles":[],"checks":[{"kind":"equal_length","refs":["A","B","C","D"],"role":"given","value":null}],"circles":[],"lines":[{"from":"A","id":"seg_AB","kind":"segment","label":null,"style":"given","to":"B"},{"from":"B","id":"seg_BC","kind":"segment","label":null,"style":"given","to":"C"},{"from":"C","id":"seg_CD","kind":"segment","label":null,"style":"given","to":"D"},{"from":"D","id":"seg_DA","kind":"segment","label":null,"style":"given","to":"A"}],"marks":[],"points":[{"draggable":false,"hidden":false,"id":"A","kind":"free","label":"A","refs":[],"value":null,"value2":null,"x":1,"y":1},{"draggable":false,"hidden":false,"id":"B","kind":"free","label":"B","refs":[],"value":null,"value2":null,"x":5,"y":1},{"draggable":false,"hidden":false,"id":"C","kind":"free","label":"C","refs":[],"value":null,"value2":null,"x":5,"y":5},{"draggable":false,"hidden":false,"id":"D","kind":"free","label":"D","refs":[],"value":null,"value2":null,"x":1,"y":5}],"scale":"exact"},"finalAnswer":{"math":"S_{\min} = \frac{19}{4}","text":"Tổng bình phương nhỏ nhất là $\dfrac{19}{4}$, đạt được ở hai cách ghi:

Cách 1: $A = \dfrac{1}{4},\; B = -\dfrac{1}{4},\; C = \dfrac{5}{4},\; D = \dfrac{7}{4}$ (tổng trên BC = 1, CD = 3, DA = 2).

Cách 2: $A = -\dfrac{1}{4},\; B = \dfrac{1}{4},\; C = \dfrac{7}{4},\; D = \dfrac{5}{4}$ (tổng trên BC = 2, CD = 3, DA = 1)."},"hints":[{"cue":"Điều kiện (ii) cho ta một đẳng thức giữa $a$ và $b$.","explanation":"Từ $a + b = 0$ suy ra $b = -a$. Như vậy chỉ còn ba ẩn tự do $a, c, d$ (thực ra sẽ còn ít hơn nữa).","focus":[],"id":"h1","level":1,"math":"b = -a","question":"Từ điều kiện (ii), bạn có thể viết $b$ theo $a$ như thế nào?","stepId":"step1"},{"cue":"Thay $b = -a$ vào các tổng trên ba cạnh, rồi thử cộng hoặc trừ các biểu thức.","explanation":"Viết $s_{BC} = c - a$, $s_{DA} = d + a$. Từ đó $c = a + s_{BC}$ và $d = s_{DA} - a$. Cộng lại: $s_{CD} = c + d = s_{BC} + s_{DA}$.","focus":[],"id":"h2","level":2,"math":"s_{CD} = s_{BC} + s_{DA}","question":"Viết tổng trên ba cạnh BC, CD, DA theo $a, c, d$. Bạn có thể tìm một mối quan hệ giữa ba tổng này không?","stepId":"step2"},{"cue":"Trong ba số 1, 2, 3, số nào bằng tổng của hai số còn lại?","explanation":"Chỉ có $3 = 1 + 2$. Vậy $s_{CD} = 3$ và $\{s_{BC}, s_{DA}\} = \{1, 2\}$, cho ra hai trường hợp.","focus":[],"id":"h3","level":3,"math":"s_{CD} = 3,\; \{s_{BC}, s_{DA}\} = \{1, 2\}","question":"Vì $s_{CD} = s_{BC} + s_{DA}$ và ba tổng là 1, 2, 3, thì $s_{CD}$ phải bằng bao nhiêu?","stepId":"step3"},{"cue":"$S = 4a^2 \pm 2a + 5 = 4\left(a \pm \dfrac{1}{4}\right)^2 + \dfrac{19}{4}$","explanation":"Mỗi trường hợp cho một tam thức bậc hai theo $a$. Hoàn thành bình phương để tìm giá trị nhỏ nhất, rồi kiểm tra điều kiện bốn số phân biệt.","focus":[],"id":"h4","level":4,"math":"S = 4a^2 - 2a + 5 = 4\left(a - \tfrac{1}{4}\right)^2 + \tfrac{19}{4}","question":"Khi đã có $c$ và $d$ theo $a$, viết $S = a^2 + b^2 + c^2 + d^2$ thành tam thức bậc hai theo $a$. Làm sao để tìm giá trị nhỏ nhất của nó?","stepId":"step4"}],"steps":[{"explanation":"Gọi bốn số ở $A, B, C, D$ lần lượt là $a, b, c, d$. Từ điều kiện (ii), tổng trên cạnh $AB$ bằng $0$, nên $b = -a$.","geometryActions":[],"id":"step1","math":"a + b = 0 \;\Rightarrow\; b = -a","reason":"Điều kiện (ii) của đề bài","title":"Đặt ẩn và dùng điều kiện (ii)","uses":[]},{"explanation":"Thay $b = -a$ vào các tổng trên ba cạnh còn lại. Từ $s_{BC} = c - a$ suy ra $c = a + s_{BC}$; từ $s_{DA} = d + a$ suy ra $d = s_{DA} - a$. Cộng hai vế: $s_{CD} = c + d = s_{BC} + s_{DA}$.","geometryActions":[],"id":"step2","math":"s_{BC} = c - a,\quad s_{CD} = c + d,\quad s_{DA} = d + a\newline c = a + s_{BC},\quad d = s_{DA} - a\newline s_{CD} = c + d = (a + s_{BC}) + (s_{DA} - a) = s_{BC} + s_{DA}","reason":"Thay thế và cộng vế theo vế","title":"Tìm mối quan hệ giữa ba tổng","uses":["step1"]},{"explanation":"Vì $s_{CD} = s_{BC} + s_{DA}$ và $\{s_{BC}, s_{CD}, s_{DA}\} = \{1, 2, 3\}$, chỉ có $3 = 1 + 2$ thỏa mãn. Vậy $s_{CD} = 3$ và $\{s_{BC}, s_{DA}\} = \{1, 2\}$, cho ra hai trường hợp.","geometryActions":[],"id":"step3","math":"s_{CD} = 3,\quad \{s_{BC},\, s_{DA}\} = \{1,\, 2\}\newline\text{TH1: } s_{BC} = 1,\; s_{DA} = 2 \qquad\text{TH2: } s_{BC} = 2,\; s_{DA} = 1","reason":"Xét trường hợp (loại trừ)","title":"Xác định hai trường hợp","uses":["step2"]},{"explanation":"Trong mỗi trường hợp, thay $c$ và $d$ theo $a$ rồi tính $S = a^2 + b^2 + c^2 + d^2$. Hoàn thành bình phương để tìm giá trị nhỏ nhất.","geometryActions":[],"id":"step4","math":"\text{TH1: } c = a+1,\; d = 2-a\newline S = a^2 + a^2 + (a+1)^2 + (2-a)^2 = 4a^2 - 2a + 5 = 4\!\left(a - \tfrac{1}{4}\right)^{\!2} + \tfrac{19}{4} \;\geq\; \tfrac{19}{4}\newline\text{TH2: } c = a+2,\; d = 1-a\newline S = a^2 + a^2 + (a+2)^2 + (1-a)^2 = 4a^2 + 2a + 5 = 4\!\left(a + \tfrac{1}{4}\right)^{\!2} + \tfrac{19}{4} \;\geq\; \tfrac{19}{4}","reason":"Hoàn thành bình phương: $(a - m)^2 \geq 0$","title":"Tính tổng bình phương và tìm giá trị nhỏ nhất","uses":["step3"]},{"explanation":"Ở TH1, $a = \dfrac{1}{4}$ cho bốn số $\dfrac{1}{4},\; -\dfrac{1}{4},\; \dfrac{5}{4},\; \dfrac{7}{4}$ — đôi một phân biệt. Ở TH2, $a = -\dfrac{1}{4}$ cho bốn số $-\dfrac{1}{4},\; \dfrac{1}{4},\; \dfrac{7}{4},\; \dfrac{5}{4}$ — cũng đôi một phân biệt. Cả hai đều thỏa mãn điều kiện (i).","geometryActions":[],"id":"step5","math":"\text{TH1: } a = \tfrac{1}{4} \Rightarrow A=\tfrac{1}{4},\; B=-\tfrac{1}{4},\; C=\tfrac{5}{4},\; D=\tfrac{7}{4}\newline\text{TH2: } a = -\tfrac{1}{4} \Rightarrow A=-\tfrac{1}{4},\; B=\tfrac{1}{4},\; C=\tfrac{7}{4},\; D=\tfrac{5}{4}\newline S_{\min} = \tfrac{19}{4}","reason":"Kiểm tra điều kiện bốn số phân biệt","title":"Kiểm tra điều kiện phân biệt và kết luận","uses":["step4"]}],"strategy":"Gọi bốn số là $a, b, c, d$. Dùng điều kiện (ii) để loại $b$, rồi tìm mối quan hệ giữa ba tổng trên các cạnh còn lại để xác định hai trường hợp. Trong mỗi trường hợp, viết tổng bình phương thành tam thức bậc hai theo $a$ và hoàn thành bình phương để tìm giá trị nhỏ nhất."}
